package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Settles a claim, fixing its due: its amount at its person's grade's rate in force on its date, rounded half to even to
 *  two decimals (a claim bound by a statement: the figure it was bound to). With no rate the due is not
 *  fixed and stays live. Refused for the user who opened it (four eyes), and for a clerk when the due
 *  is above the sheet's clerk limit (a due that is n/a is within any limit; a steward settles anything). */
public class SettleClaim {
    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            PersonRepository people, RateRepository rates, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings)
            throws ClaimStatusException, ClaimLimitException, PeriodClosedException {
        periods.requireOpen(claim.getSheetId(), claim.getDate());
        ClaimStatus settled = ClaimStatus.valueOf(claim.getStatus()).moveTo(ClaimStatus.SETTLED);
        if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(by == null ? "" : by)) {
            throw new ClaimStatusException("The user who opened a claim cannot settle it");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        Rate rate = person == null ? null : rates.find(claim.getSheetId(), person.getGrade(),
                LocalDate.parse(claim.getDate()));
        // A claim bound by a statement settles at the figure it was bound to.
        String due = claim.isStated() ? claim.getStatedDue()
                : rate == null ? null : Dues.of(claim.getAmount(), rate.pct());
        if (due != null && Role.CLERK.equals(roles.roleOf(claim.getSheetId(), by == null ? "" : by))) {
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            if (limit != null && new BigDecimal(due).compareTo(limit) > 0) {
                throw new ClaimLimitException("A clerk cannot settle a claim whose due is above the clerk limit");
            }
        }
        claim.setStatus(settled.name());
        claim.setSettledDue(due);
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Takes a statement of the person: records their due-total now (the sum of their counting claims'
 *  due figures, n/a ones skipped; n/a when their grade has no rate on the sheet's today and none of
 *  those claims keeps a settled or bound figure) on the sheet's today, and binds each counting claim
 *  to the figure it shows now; a claim that does not count is unbound. */
public class TakeStatement {
    public void take(@Val Person person, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        List<Claim> own = claims.listOf(sheetId, person.getId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int bound = 0;
        for (Claim c : own) {
            if (!c.isCounting()) {
                c.bind(false, null);
            } else {
                Rate rate = rates.find(sheetId, person.getGrade(), LocalDate.parse(c.getDate()));
                String due = c.due(rate == null ? null : Dues.of(c.getAmount(), rate.pct()));
                kept |= c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null);
                if (due != null) total = total.add(new BigDecimal(due));
                c.bind(true, due);
                bound++;
            }
            claims.updateBinding(c);
        }
        boolean na = rates.find(sheetId, person.getGrade(), today) == null && !kept;
        person.stated(na ? null : total.toPlainString(), today.toString(), bound);
        people.updateStatements(person);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Closes a period, fixing its due-total as it is now: the due of the claims that count whose date
 *  falls in it (n/a ones skipped, and OPEN ones of people on hold), as the screen shows them.
 *  Refused when it is already closed. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            ClaimRepository claims, PersonRepository people, RateRepository rates,
            Out<Period> period) throws InvalidPeriodException, PeriodClosedException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (found.closed()) {
            throw new PeriodClosedException("The period is already closed");
        }
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.list(id)) {
            if (!c.isCounting() || !found.contains(c.getDate())) continue;
            Person person = people.find(id, c.getPersonId());
            if (person != null && !person.countsLive(c)) continue;
            Rate rate = person == null ? null
                    : rates.find(id, person.getGrade(), LocalDate.parse(c.getDate()));
            String due = c.due(rate == null ? null : Dues.of(c.getAmount(), rate.pct()));
            if (due != null) total = total.add(new BigDecimal(due));
        }
        period.set(periods.close(found, total, by == null ? "" : by));
    }
}
